`ChunkCard`의 기능을 대폭 강화하고 메인 페이지 로직을 연결합니다.

#### **A. ChunkCard 컴포넌트 (기능 통합)**

```tsx
interface ChunkCardProps {
  result: TranslationResult;
  isExpanded: boolean;
  onToggle: (index: number) => void;
  onRetry: (index: number) => void;      // 개별 재번역
  onDiscard: (index: number) => void;    // 번역 비우기
  onUpdate: (index: number, text: string) => void; // 직접 수정
}

const ChunkCard = React.memo(function ChunkCard({ 
  result, isExpanded, onToggle, onRetry, onDiscard, onUpdate 
}: ChunkCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editedText, setEditedText] = useState(result.translatedText);

  // 편집 모드 진입
  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditedText(result.translatedText);
    setIsEditing(true);
    if (!isExpanded) onToggle(result.chunkIndex);
  };

  // 저장
  const handleSave = () => {
    onUpdate(result.chunkIndex, editedText);
    setIsEditing(false);
  };

  // 비우기
  const handleDiscardClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('번역 내용을 비우고 재번역 대기 상태로 만들까요?')) {
      onDiscard(result.chunkIndex);
    }
  };

  return (
    <div className={`border rounded-lg overflow-hidden ${result.success ? 'border-gray-200' : 'border-red-300'}`}>
      {/* 헤더 */}
      <div className="..." onClick={() => onToggle(result.chunkIndex)}>
        {/* ... 좌측 정보 ... */}
        <div className="flex items-center gap-2">
          {/* [1] 비우기 버튼 (성공 상태일 때만) */}
          {result.success && !isEditing && (
            <IconButton 
              onClick={handleDiscardClick} 
              icon={<Trash2 className="w-4 h-4" />} 
              className="text-red-400 hover:text-red-600 hover:bg-red-50"
              title="번역 비우기"
            />
          )}
          {/* [2] 재번역 버튼 (실패 상태일 때) */}
          {!result.success && (
            <IconButton 
              onClick={(e) => { e.stopPropagation(); onRetry(result.chunkIndex); }} 
              icon={<RefreshCw className="w-4 h-4" />}
              className="text-blue-600 hover:text-blue-800"
              title="즉시 재번역"
            />
          )}
          {/* [3] 수정 버튼 */}
          {!isEditing && (
            <IconButton 
              onClick={handleEditClick} 
              icon={<Edit2 className="w-4 h-4" />}
              className="text-gray-500 hover:text-gray-700" 
              title="직접 수정"
            />
          )}
          {/* ... 기존 버튼들 ... */}
        </div>
      </div>

      {/* 본문 */}
      {isExpanded && (
        <div className="p-4 grid md:grid-cols-2 gap-4">
          <div className="bg-gray-100 rounded p-3"><pre>{result.originalText}</pre></div>
          <div>
            {isEditing ? (
              <div className="space-y-2">
                <textarea 
                  className="w-full h-48 border rounded p-2" 
                  value={editedText} 
                  onChange={(e) => setEditedText(e.target.value)} 
                />
                <div className="flex justify-end gap-2">
                  <Button size="sm" variant="ghost" onClick={() => setIsEditing(false)}>취소</Button>
                  <Button size="sm" variant="primary" onClick={handleSave}>저장</Button>
                </div>
              </div>
            ) : (
              <div className={`rounded p-3 ${result.success ? 'bg-green-50' : 'bg-red-50'}`}>
                <pre>{result.translatedText || '(번역 내용 없음)'}</pre>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
});
```

#### **B. ReviewPage 메인 로직 (핸들러 통합)**

```tsx
export function ReviewPage() {
  const { results, updateResult, combineResultsToText } = useTranslationStore();
  const { retryFailedChunks, retrySingleChunk } = useTranslation();

  // [1] 번역 비우기 핸들러
  const handleDiscard = useCallback((chunkIndex: number) => {
    updateResult(chunkIndex, {
      success: false,
      translatedText: '',
      error: '사용자 요청에 의한 재번역 대기'
    });
    // 비운 후에는 전체 텍스트 갱신 필요 없음 (어차피 비어있음)
  }, [updateResult]);

  // [2] 직접 수정 핸들러
  const handleUpdateText = useCallback((chunkIndex: number, newText: string) => {
    updateResult(chunkIndex, {
      translatedText: newText,
      success: true,
      error: undefined
    });
    combineResultsToText(); // 전체 텍스트 동기화
  }, [updateResult, combineResultsToText]);

  // [3] 개별 재번역 핸들러
  const handleSingleRetry = useCallback((chunkIndex: number) => {
    retrySingleChunk(chunkIndex);
  }, [retrySingleChunk]);

  // [4] 일괄 재시도 핸들러
  const handleBatchRetry = useCallback(() => {
    retryFailedChunks();
  }, [retryFailedChunks]);

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white rounded-lg shadow p-6">
        {/* 상단 헤더 및 일괄 작업 버튼 */}
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <CheckCircle className="w-5 h-5" /> 검토 및 수정
